INSERT INTO public.pairings (song_a_id,song_b_id,tests,hypothesis,lane,active,is_bootstrap)
SELECT sa.id,sb.id,p.tests::text[],p.h,'alternative',false,false FROM (VALUES
('Last Nite','Take Me Out','{movement,confidence}','garage scruff vs. dancefloor precision'),
('Mr. Brightside','Use Somebody','{scale,community}','which arena anthem actually unites the room'),
('Maps','Seven Nation Army','{tension,confidence}','vulnerability vs. riff swagger'),
('Float On','Time to Pretend','{perspective,atmosphere}','optimism as coping vs. hedonism as dread'),
('Banquet','Kids','{movement,texture}','post-punk legs vs. synth nostalgia'),
('Rebellion (Lies)','Dog Days Are Over','{community,transformation}','two roads to catharsis'),
('Such Great Heights','Mr. Brightside','{immersion,scale}','bedroom intimacy vs. stadium jealousy'),
('I Bet You Look Good on the Dancefloor','Nine in the Afternoon','{confidence,movement}','speed vs. theatre'),
('Do I Wanna Know?','Lonely Boy','{tension,confidence}','slow burn vs. bar-band strut'),
('Pumped Up Kicks','Take a Walk','{perspective,movement}','dark lyric / bright sound, twice removed'),
('Midnight City','Clearest Blue','{atmosphere,transformation}','widescreen haze vs. engineered release'),
('Royals','Feel It Still','{perspective,confidence}','anti-luxury vs. retro cool'),
('Ho Hey','Riptide','{community,movement}','stomp-folk sincerity vs. beachside charm'),
('Somebody That I Used to Know','Breezeblocks','{perspective,texture}','breakup accounting vs. art-school menace'),
('The Mother We Share','Shut Up and Dance','{community,movement}','synth warmth vs. pure floor-filler'),
('Budapest','Royals','{tension,perspective}','contentment vs. critique (low/high control)'),
('good 4 u','drivers license','{tension,transformation}','rage vs. grief from the same pen'),
('Heat Waves','As It Was','{atmosphere,community}','two pandemic-era smashes, haze vs. gloss'),
('Anti-Hero','Not Strong Enough','{perspective,community}','self-laceration solo vs. in harmony'),
('Kyoto','Messy','{perspective,tension}','deadpan vs. raw nerve'),
('Beautiful Things','Ordinary','{scale,community}','which 2020s ballad actually earned the room'),
('Seven Nation Army','good 4 u','{confidence,tension}','riff minimalism across two decades'),
('Midnight City','Heat Waves','{atmosphere,immersion}','2011 haze vs. 2020 haze'),
('Mr. Brightside','As It Was','{community,scale}','the millennial anthem vs. the zoomer one')
) p(a,b,tests,h)
JOIN public.songs sa ON sa.title=p.a AND sa.scoring_version='cat06-draft-1'
JOIN public.songs sb ON sb.title=p.b AND sb.scoring_version='cat06-draft-1';